if(benchmark&&fs.existsSync(benchmark))fs.copyFileSync(benchmark,out);else await sharp(source).avif({quality:70,effort:6,chromaSubsampling:'4:4:4'}).toFile(out);
const before=await sharp(source).metadata(),after=await sharp(out).metadata();if(before.width!==after.width||before.height!==after.height||before.hasAlpha!==after.hasAlpha)throw Error('Metadata mismatch '+source);
records.push({source,out,before:fs.statSync(source).size,bytes:fs.statSync(out).size,width:after.width,height:after.height,alpha:!!after.hasAlpha,sha256:crypto.createHash('sha256').update(fs.readFileSync(out)).digest('hex')});console.log('Converted '+records.length+'/'+sources.length+' '+out);
}}
(async()=>{await Promise.all(Array.from({length:4},worker));
for(const file of files){const archived=path.join('tmp/artwork-originals',file);fs.mkdirSync(path.dirname(archived),{recursive:true});fs.copyFileSync(file,archived);}
